import { BaseMysqlStore } from './BaseMysqlStore.js';
import { affectedRows, queryFirst, toBytes } from './helpers.js';
const DEFAULT_RETRY_TTL_MS = 60 * 1000;
function isObjectRecord(value) {
    return !!value && typeof value === 'object' && !Array.isArray(value);
}
export class WaRetryMysqlStore extends BaseMysqlStore {
    constructor(options, ttlMs = DEFAULT_RETRY_TTL_MS) {
        super(options, ['retry']);
        if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
            throw new Error('retry ttlMs must be a positive finite number');
        }
        this.ttlMs = ttlMs;
    }
    getTtlMs() {
        return this.ttlMs;
    }
    supportsRawReplayPayload() {
        return false;
    }
    async getOutboundRequesterStatus(messageId, requesterDeviceJid) {
        await this.ensureReady();
        const row = queryFirst(await this.pool.execute(`SELECT requesters_json
             FROM ${this.t('retry_outbound_messages')}
             WHERE session_id = ? AND message_id = ?
             LIMIT 1`, [this.sessionId, messageId]));
        if (!row) {
            return null;
        }
        const requestersJson = row.requesters_json !== null && row.requesters_json !== undefined
            ? row.requesters_json instanceof Uint8Array
                ? new TextDecoder().decode(row.requesters_json)
                : String(row.requesters_json)
            : null;
        if (!requestersJson) {
            return null;
        }
        const requesters = this.parseRequesterStatusPayload(requestersJson);
        if (requesters.eligible.length === 0) {
            return null;
        }
        let isEligible = false;
        for (let index = 0; index < requesters.eligible.length; index += 1) {
            if (requesters.eligible[index] === requesterDeviceJid) {
                isEligible = true;
                break;
            }
        }
        if (!isEligible) {
            return {
                eligible: false,
                delivered: false
            };
        }
        for (let index = 0; index < requesters.delivered.length; index += 1) {
            if (requesters.delivered[index] === requesterDeviceJid) {
                return {
                    eligible: true,
                    delivered: true
                };
            }
        }
        return {
            eligible: true,
            delivered: false
        };
    }
    async upsertOutboundMessage(record) {
        await this.ensureReady();
        const requestersJson = this.serializeRequesterStatusPayload(record.eligibleRequesterDeviceJids, record.deliveredRequesterDeviceJids);
        if (!(record.replayPayload instanceof Uint8Array)) {
            throw new Error('retry_outbound_messages.replay_payload must be Uint8Array');
        }
        const replayPayload = record.replayPayload;
        await this.pool.execute(`INSERT INTO ${this.t('retry_outbound_messages')} (
                session_id,
                message_id,
                to_jid,
                replay_mode,
                replay_payload,
                requesters_json,
                state,
                updated_at_ms,
                expires_at_ms
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON DUPLICATE KEY UPDATE
                to_jid = VALUES(to_jid),
                replay_mode = VALUES(replay_mode),
                replay_payload = VALUES(replay_payload),
                requesters_json = VALUES(requesters_json),
                state = VALUES(state),
                updated_at_ms = VALUES(updated_at_ms),
                expires_at_ms = VALUES(expires_at_ms)`, [
            this.sessionId,
            record.messageId,
            record.toJid,
            record.replayMode,
            replayPayload,
            requestersJson,
            record.state,
            record.updatedAtMs,
            record.expiresAtMs
        ]);
    }
    async deleteOutboundMessage(messageId) {
        await this.ensureReady();
        return affectedRows(await this.pool.execute(`DELETE FROM ${this.t('retry_outbound_messages')}
             WHERE session_id = ? AND message_id = ?`, [this.sessionId, messageId]));
    }
    async getOutboundMessage(messageId) {
        await this.ensureReady();
        const row = queryFirst(await this.pool.execute(`SELECT
                message_id,
                to_jid,
                replay_mode,
                replay_payload,
                requesters_json,
                state,
                updated_at_ms,
                expires_at_ms
            FROM ${this.t('retry_outbound_messages')}
            WHERE session_id = ? AND message_id = ?`, [this.sessionId, messageId]));
        if (!row) {
            return null;
        }
        const requestersJson = row.requesters_json !== null && row.requesters_json !== undefined
            ? row.requesters_json instanceof Uint8Array
                ? new TextDecoder().decode(row.requesters_json)
                : String(row.requesters_json)
            : null;
        const requesters = requestersJson
            ? this.parseRequesterStatusPayload(requestersJson)
            : {
                eligible: [],
                delivered: []
            };
        return {
            messageId: String(row.message_id),
            toJid: String(row.to_jid),
            eligibleRequesterDeviceJids: requesters.eligible.length > 0 ? requesters.eligible : undefined,
            deliveredRequesterDeviceJids: requesters.delivered.length > 0 ? requesters.delivered : undefined,
            replayMode: String(row.replay_mode),
            replayPayload: toBytes(row.replay_payload),
            state: String(row.state),
            updatedAtMs: Number(row.updated_at_ms),
            expiresAtMs: Number(row.expires_at_ms)
        };
    }
    async updateOutboundMessageState(messageId, state, updatedAtMs, expiresAtMs) {
        await this.ensureReady();
        await this.pool.execute(`UPDATE ${this.t('retry_outbound_messages')}
             SET state = ?, updated_at_ms = ?, expires_at_ms = ?
             WHERE session_id = ? AND message_id = ?`, [state, updatedAtMs, expiresAtMs, this.sessionId, messageId]);
    }
    async markOutboundRequesterDelivered(messageId, requesterDeviceJid, updatedAtMs, expiresAtMs) {
        await this.withTransaction(async (conn) => {
            const row = queryFirst(await conn.execute(`SELECT requesters_json
                 FROM ${this.t('retry_outbound_messages')}
                 WHERE session_id = ? AND message_id = ?
                 FOR UPDATE`, [this.sessionId, messageId]));
            if (!row) {
                return;
            }
            const requestersJson = row.requesters_json !== null && row.requesters_json !== undefined
                ? row.requesters_json instanceof Uint8Array
                    ? new TextDecoder().decode(row.requesters_json)
                    : String(row.requesters_json)
                : null;
            if (!requestersJson) {
                return;
            }
            const requesters = this.parseRequesterStatusPayload(requestersJson);
            let isEligible = false;
            for (let index = 0; index < requesters.eligible.length; index += 1) {
                if (requesters.eligible[index] === requesterDeviceJid) {
                    isEligible = true;
                    break;
                }
            }
            if (!isEligible) {
                return;
            }
            for (let index = 0; index < requesters.delivered.length; index += 1) {
                if (requesters.delivered[index] === requesterDeviceJid) {
                    return;
                }
            }
            const nextRequestersJson = this.serializeRequesterStatusPayload(requesters.eligible, [
                ...requesters.delivered,
                requesterDeviceJid
            ]);
            await conn.execute(`UPDATE ${this.t('retry_outbound_messages')}
                 SET requesters_json = ?, updated_at_ms = ?, expires_at_ms = ?
                 WHERE session_id = ? AND message_id = ?`, [nextRequestersJson, updatedAtMs, expiresAtMs, this.sessionId, messageId]);
        });
    }
    async incrementInboundCounter(messageId, requesterJid, _updatedAtMs, expiresAtMs) {
        return this.withTransaction(async (conn) => {
            await conn.execute(`INSERT INTO ${this.t('retry_inbound_counters')} (
                    session_id, message_id, requester_jid, retry_count, expires_at_ms
                ) VALUES (?, ?, ?, LAST_INSERT_ID(1), ?)
                ON DUPLICATE KEY UPDATE
                    retry_count = LAST_INSERT_ID(retry_count + 1),
                    expires_at_ms = VALUES(expires_at_ms)`, [this.sessionId, messageId, requesterJid, expiresAtMs]);
            const row = queryFirst(await conn.execute('SELECT LAST_INSERT_ID() AS retry_count', []));
            return row ? Number(row.retry_count) : 1;
        });
    }
    async cleanupExpired(nowMs) {
        await this.ensureReady();
        const outboundCount = affectedRows(await this.pool.execute(`DELETE FROM ${this.t('retry_outbound_messages')}
             WHERE session_id = ? AND expires_at_ms <= ?`, [this.sessionId, nowMs]));
        const inboundCount = affectedRows(await this.pool.execute(`DELETE FROM ${this.t('retry_inbound_counters')}
             WHERE session_id = ? AND expires_at_ms <= ?`, [this.sessionId, nowMs]));
        return outboundCount + inboundCount;
    }
    async clear() {
        await this.ensureReady();
        await this.pool.execute(`DELETE FROM ${this.t('retry_outbound_messages')} WHERE session_id = ?`, [this.sessionId]);
        await this.pool.execute(`DELETE FROM ${this.t('retry_inbound_counters')} WHERE session_id = ?`, [this.sessionId]);
    }
    serializeRequesterStatusPayload(eligibleRequesterDeviceJids, deliveredRequesterDeviceJids) {
        const eligible = this.toUniqueStrings(eligibleRequesterDeviceJids ?? [], 'requesters_json.eligible');
        if (eligible.length === 0) {
            return null;
        }
        const eligibleSet = new Set(eligible);
        const delivered = this.toUniqueStrings(deliveredRequesterDeviceJids ?? [], 'requesters_json.delivered').filter((jid) => eligibleSet.has(jid));
        const payload = delivered.length > 0
            ? {
                eligible,
                delivered
            }
            : {
                eligible
            };
        return JSON.stringify(payload);
    }
    parseRequesterStatusPayload(raw) {
        const parsed = JSON.parse(raw);
        if (!isObjectRecord(parsed)) {
            throw new Error('retry_outbound_messages.requesters_json must be an object');
        }
        const eligibleRaw = parsed.eligible;
        if (!Array.isArray(eligibleRaw)) {
            throw new Error('retry_outbound_messages.requesters_json.eligible must be an array');
        }
        const eligible = this.toUniqueStrings(eligibleRaw, 'requesters_json.eligible');
        const deliveredRaw = parsed.delivered;
        if (deliveredRaw !== undefined && !Array.isArray(deliveredRaw)) {
            throw new Error('retry_outbound_messages.requesters_json.delivered must be an array');
        }
        const eligibleSet = new Set(eligible);
        const delivered = this.toUniqueStrings(Array.isArray(deliveredRaw) ? deliveredRaw : [], 'requesters_json.delivered').filter((jid) => eligibleSet.has(jid));
        return {
            eligible,
            delivered
        };
    }
    toUniqueStrings(values, field) {
        const deduped = new Set();
        for (let index = 0; index < values.length; index += 1) {
            const rawValue = values[index];
            if (typeof rawValue !== 'string') {
                throw new Error(`${field} must contain only strings`);
            }
            const normalized = rawValue.trim();
            if (!normalized) {
                continue;
            }
            deduped.add(normalized);
        }
        return Array.from(deduped);
    }
}
